52	// Two rendering roots: Preact for English, React+Lit WC for Chinese.
53	// Only one is visible at a time, toggled by the i18next listener below.
54	const reactRoot =
55	  document.getElementById("react-root") ?? document.createElement("react-root");
56	
57	const preactRoot =
58	  document.getElementById("preact-root") ??
59	  document.createElement("react-root");
60	
61	if (!reactRoot.id) {
62	  reactRoot.id = "react-root";
63	}
64	if (!preactRoot.id) {
65	  preactRoot.id = "preact-root";
66	}
67	if (!document.body.contains(reactRoot)) {
68	  document.body.appendChild(reactRoot);
69	}
70	if (!document.body.contains(preactRoot)) {
71	  document.body.appendChild(preactRoot);
72	}
73	function updateVisibility(lang: string): void {
74	  const en = lang === "en";
75	  reactRoot.classList.toggle("hidden", en);
76	  preactRoot.classList.toggle("hidden", !en);
77	}
78	
79	// Initial visibility based on current language (default: en -> Preact).
80	updateVisibility(i18next.language);
81	
82	// Preact tree (English mode).
83	mountPreact(preactRoot);
84	// React tree (Chinese mode, Lit Web Components via @lit/react).
85	mountReactWC(reactRoot);
86	
87	// Toggle visibility on language change.
88	i18next.on("languageChanged", updateVisibility);
