24	import { useCallback, useSyncExternalStore } from "react";
25	import { i18next, resumeData } from "@/i18n";
26	import { ResumeHeaderWC, SectionEduWC, SectionListWC } from "@/components/wc";
27	
28	/**
29	 * Subscribes to i18next language changes and returns the current
30	 * resume data snapshot. Triggers re-render whenever the language switches.
31	 */
32	function useResumeData() {
33	  const subscribe = useCallback((onStoreChange: () => void) => {
34	    const handler = () => onStoreChange();
35	    i18next.on("languageChanged", handler);
36	    return () => {
37	      i18next.off("languageChanged", handler);
38	    };
39	  }, []);
40	  return useSyncExternalStore(
41	    subscribe,
42	    () => resumeData.value,
43	    () => resumeData.value,
44	  );
45	}
46	
47	/**
48	 * React application composed of Lit Web Components wrapped via @lit/react.
49	 *
50	 * Reads resume data from the Preact signal (which i18n/index.ts keeps
51	 * in sync with i18next), then pushes it down as props to each WC.
52	 */
53	export default function AppReactWC(): React.JSX.Element {
54	  const data = useResumeData();
55	
56	  const handleToggleLocale = useCallback(() => {
57	    const next = i18next.language === "en" ? "zh" : "en";
58	    void i18next.changeLanguage(next);
59	  }, []);
60	
61	  const sections = [
62	    { title: data.headers.skills, items: data.skills },
63	    { title: data.headers.works, items: data.works },
64	    { title: data.headers.projects, items: data.projects },
65	    { title: data.headers.research, items: [data.research] },
66	  ];
67	
68	  return (
69	    <div className="min-h-dvh w-full bg-neutral-50 text-neutral-900">
70	      <div className="mx-auto flex w-full max-w-4xl flex-col gap-1.5">
71	        <ResumeHeaderWC
72	          name={data.name}
73	          about={data.about}
74	          tel={data.tel}
75	          email={data.email}
76	          github={data.github}
77	          labels={data.labels}
78	          onToggleLocale={handleToggleLocale}
79	        />
80	        <SectionEduWC header={data.headers.edu} edu={data.edu} />
81	        {sections.map((section) => (
82	          <SectionListWC
83	            key={section.title}
84	            title={section.title}
85	            items={section.items}
86	          />
87	        ))}
88	      </div>
89	    </div>
90	  );
91	}
