23	/**
24	 * View setup registry: viewPath -> ViewSetup function.
25	 *
26	 * In the functional system, the registry stores `ViewSetup` functions (not
27	 * View classes). `defineView(setupFn)` returns the setup function, which is
28	 * registered here and later called by `mountCtx` to create a `ViewCtx`.
29	 */
30	import { parseUri } from "./utils";
31	import type { ViewSetup } from "./types";
32	
33	/** Registry of view setup functions keyed by path. */
34	const viewSetupRegistry: Record<string, ViewSetup> = {};
35	
36	/**
37	 * Look up a previously registered View setup function by path.
38	 * Returns `undefined` if no setup is registered for `path`.
39	 */
40	export function getViewClass(path: string): ViewSetup | undefined {
41	  return viewSetupRegistry[path];
42	}
43	
44	/**
45	 * Register a View setup function for a given view path.
46	 * Called after module loading completes (or up front during boot).
47	 */
48	export function registerViewClass(viewPath: string, setup: ViewSetup): void {
49	  const parsed = parseUri(viewPath);
50	  const path = parsed.path;
51	  if (path) {
52	    viewSetupRegistry[path] = setup;
53	  }
54	}
55	
56	/**
57	 * Invalidate a View setup from the registry.
58	 * Used by HMR to force re-loading of a view module.
59	 */
60	export function invalidateViewClass(viewPath: string): void {
61	  const parsed = parseUri(viewPath);
62	  const path = parsed.path;
63	  if (path) {
64	    Reflect.deleteProperty(viewSetupRegistry, path);
65	  }
66	}
67	
68	/**
69	 * Get the full view setup registry (for HMR / debugging).
70	 */
71	export function getViewClassRegistry(): Record<string, ViewSetup> {
72	  return viewSetupRegistry;
73	}
